const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const [a, b, c] = line.split(' ').map(Number);
    const sum = a + b + c;
    if (sum % 2 !== 0) {
        console.log("Impossible");
        rl.close();
        return;
    }
    const s = sum / 2;
    if (s < a || s < b || s < c) {
        console.log("Impossible");
        rl.close();
        return;
    }
    const x = s - c;
    const y = s - a;
    const z = s - b;
    console.log(`${x} ${y} ${z}`);
    rl.close();
});
