const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const [a, b, c] = line.split(' ').map(Number);
    let found = false;
    let result = '';
    for (let x = 0; x <= Math.min(a, b); x++) {
        for (let y = 0; y <= Math.min(b, c); y++) {
            const z = a - x;
            if (z < 0 || z > c) continue;
            if (x + y === b && y + z === c) {
                result = `${x} ${y} ${z}`;
                found = true;
                break;
            }
        }
        if (found) break;
    }
    console.log(found ? result : 'Impossible');
    rl.close();
});
